<?php
declare(strict_types=1);
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(403);exit;}
function staff_id(string $id): string {if(!preg_match('/\A[0-9a-f]{8}(?:-[0-9a-f]{4}){3}-[0-9a-f]{12}\z/',$id))throw new RuntimeException('Staff unavailable.');return $id;}
function staff_rows(array $b): array {$all=[];for($page=0;$page<100;$page++){$rows=api('/rest/v1/business_staff?business_id=eq.'.rawurlencode($b['id']).'&environment=eq.'.profile_env().'&select=*&order=name.asc,id.asc&limit=100&offset='.($page*100),[],'GET',$_SESSION['auth']['access_token']);$all=array_merge($all,$rows);if(count($rows)<100)return $all;}throw new RuntimeException('Staff list is too large. Please contact support.');}
function staff_values(): array {$d=[];foreach(['name'=>120,'email'=>254,'phone'=>40] as $k=>$max){$v=$_POST[$k]??'';if(!is_string($v)||!preg_match('//u',$v)||mb_len(trim($v))>$max||preg_match('/[\x00-\x1f\x7f]/',$v))throw new RuntimeException('Check staff details.');$d[$k]=trim($v);}if(mb_len($d['name'])<2||($d['email']!==''&&!filter_var($d['email'],FILTER_VALIDATE_EMAIL))||($d['phone']!==''&&(!preg_match('/\A[+0-9 ()-]{5,40}\z/',$d['phone'])||strlen(preg_replace('/\D/','',$d['phone']))<5)))throw new RuntimeException('Check staff details.');return $d;}
function staff_summary(array $r): void {$names=implode(', ',array_map(fn($s)=>$s['name'].($s['active']?'':' (inactive)'),$r['assigned_staff']??[]));echo '<p class="muted">Staff: '.esc($names?:'Unassigned').'</p>';}
function staff_warnings(array $r,string $zone): void {if(empty($r['conflicts']))return;echo '<div class="alert" role="status"><strong>Overlapping assignments</strong>';foreach($r['conflicts'] as $c){$at=(new DateTimeImmutable($c['starts_at']))->setTimezone(new DateTimeZone($zone));echo '<p>'.esc($c['name']).' · <a href="bookings.php?id='.esc($c['booking_id']).'">Booking '.esc(strtoupper(substr($c['booking_id'],0,8))).'</a> · '.esc($at->format('d M Y H:i')).' · '.(int)$c['duration_minutes'].' min</p>';}echo '<small>Times in '.esc(str_replace('_',' ',$zone)).'. Scheduled and In Progress bookings are checked, including other dates and pages. Overlaps are warnings; saving remains allowed.</small></div>';}
